c.STDIO:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[10002];
    int counts[26] = {0};
    fgets(line, sizeof(line), stdin);
    for (int i = 0; line[i] != '\0'; ++i) {
        char letter = line[i];
        if (letter >= 'A' && letter <= 'Z') {
            letter = (char)(letter - 'A' + 'a');
        }
        if (letter >= 'a' && letter <= 'z') {
            ++counts[letter - 'a'];
        }
    }
    int best = 0;
    for (int i = 1; i < 26; ++i) {
        if (counts[i] > counts[best]) {
            best = i;
        }
    }
    printf("%c %d\n", 'a' + best, counts[best]);
    return 0;
}

